/// All the built-in simple language function names (in lower case, in order).
pub fn get_functions() -> &'static [&'static str] {
    SIMPLE_FUNCTIONS
}

#[cfg(test)]
mod tests {
    #[test]
    fn functions() {
        assert!(super::get_functions().contains(&"body"));
        assert!(super::get_functions()
            .iter()
            .all(|f| f.to_lowercase() == *f));
    }
}
